const root = $input.first().json;
const binary = $input.first().binary || {};

const envelope = root.body || {};
const data = envelope.data || {};
const message = data.message || {};
const key = data.key || {};

// ---------- TEXT (WhatsApp) ----------
const conversation = message.conversation || null;
const extendedText = message.extendedTextMessage?.text || null;
const imageCaption = message.imageMessage?.caption || null;
const documentCaption = message.documentMessage?.caption || null;
let textContent = conversation || extendedText || imageCaption || documentCaption || null;
let hasText = !!textContent;

// ---------- IMAGE / PDF (WhatsApp) ----------
const imageMessage =
  message.imageMessage ||
  message?.viewOnceMessage?.message?.imageMessage ||
  message?.ephemeralMessage?.message?.imageMessage ||
  null;
let hasImage = !!imageMessage;
const resolvedImageCaption = imageMessage?.caption || '';

const documentMessage =
  message.documentMessage ||
  message?.viewOnceMessage?.message?.documentMessage ||
  message?.ephemeralMessage?.message?.documentMessage ||
  null;
const mimeType = documentMessage?.mimetype?.toLowerCase() || '';
const fileName = documentMessage?.fileName?.toLowerCase() || '';
let hasPdf = !!(documentMessage && (mimeType.includes('pdf') || fileName.endsWith('.pdf')));

// ---------- DIRECT UPLOAD (multipart from admin frontend) ----------
let directUpload = false;
let directBinary = null;
let directMime = null;
let directFileName = null;

for (const [propName, b] of Object.entries(binary)) {
  if (!b || !b.mimeType) continue;
  const mt = String(b.mimeType).toLowerCase();
  const fn = String(b.fileName || '').toLowerCase();
  if (mt.startsWith('image/')) {
    hasImage = true;
    directUpload = true;
    directBinary = b;
    directMime = mt;
    directFileName = fn;
    break;
  }
  if (mt === 'application/pdf' || fn.endsWith('.pdf')) {
    hasPdf = true;
    directUpload = true;
    directBinary = b;
    directMime = mt;
    directFileName = fn;
    break;
  }
}

// Multipart text field from direct upload (admin frontend)
const directText = (root && root.body && typeof root.body.text === 'string') ? root.body.text.trim() : '';
if (directText) {
  if (!textContent) textContent = directText;
  hasText = true;
  directUpload = true;
}

const jobId = 'job_' + Date.now() + '_' + Math.random().toString(36).substring(2, 11);
const senderJid = key.remoteJid || envelope.sender || (directUpload ? 'manual_upload' : 'unknown');

const out = {
  json: {
    jobId,
    senderJid,
    messageId: key.id || null,
    remoteJid: key.remoteJid || null,
    fromMe: key.fromMe || false,
    instanceName: envelope.instance || null,
    originalPayload: root,
    originalBody: envelope,
    hasText,
    hasImage,
    hasPdf,
    directUpload,
    directMime,
    directFileName,
    text: textContent,
    imageCaption: resolvedImageCaption,
    image: hasImage ? imageMessage : null,
    pdf: hasPdf ? documentMessage : null
  }
};

if (directUpload && directBinary) {
  out.binary = {};
  if (hasImage) out.binary.image = directBinary;
  if (hasPdf) out.binary.document = directBinary;
}

return [out];

// ============================================================================
// NŒUD : Collect & Dynamic Merge (HARMONISÉ - cohérent avec Format Text)
// PLACE : Après Merge 2, AVANT Compute Slugs
//
// RÔLE : Fusionner les outputs des 3 branches (texte, image, PDF) en un seul
//        payload cohérent avec normalisation FR + dédup.
// ============================================================================

const items = $input.all().map(i => i.json);

// ----------------------------------------------------------------------------
// HELPERS (mêmes fonctions que Format Text Result)
// ----------------------------------------------------------------------------
function normalizeNumber(v) {
  if (typeof v === 'number' && Number.isFinite(v)) return v;
  if (typeof v === 'string') {
    const cleaned = v.trim().replace(/\s+/g, '').replace(/,/g, '.').replace(/[^\d.-]/g, '');
    if (!cleaned || cleaned === '.' || cleaned === '-' || cleaned === '-.') return null;
    const num = Number(cleaned);
    return Number.isFinite(num) ? num : null;
  }
  return null;
}

function uniqueStrings(arr) {
  return [...new Set((arr || []).filter(v => typeof v === 'string' && v.trim() !== ''))];
}

function stripAccents(s) {
  return String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();
}

// MAPPING ANGLAIS → FRANÇAIS POUR LES PAYS
const COUNTRY_EN_TO_FR = {
  'azerbaijan': 'Azerbaïdjan', 'turkey': 'Turquie', 'turkiye': 'Turquie', 'türkiye': 'Turquie',
  'morocco': 'Maroc', 'tunisia': 'Tunisie', 'egypt': 'Égypte', 'spain': 'Espagne',
  'france': 'France', 'italy': 'Italie', 'greece': 'Grèce', 'cyprus': 'Chypre',
  'portugal': 'Portugal', 'malaysia': 'Malaisie', 'thailand': 'Thaïlande',
  'maldives': 'Maldives', 'mauritius': 'Maurice', 'seychelles': 'Seychelles',
  'indonesia': 'Indonésie', 'china': 'Chine', 'japan': 'Japon',
  'south korea': 'Corée du Sud', 'singapore': 'Singapour',
  'united arab emirates': 'Émirats Arabes Unis', 'uae': 'Émirats Arabes Unis', 'dubai': 'Émirats Arabes Unis',
  'qatar': 'Qatar', 'saudi arabia': 'Arabie Saoudite', 'jordan': 'Jordanie',
  'lebanon': 'Liban', 'oman': 'Oman', 'india': 'Inde', 'sri lanka': 'Sri Lanka',
  'vietnam': 'Vietnam', 'algeria': 'Algérie', 'germany': 'Allemagne',
  'austria': 'Autriche', 'switzerland': 'Suisse', 'belgium': 'Belgique',
  'netherlands': 'Pays-Bas', 'united kingdom': 'Royaume-Uni', 'uk': 'Royaume-Uni',
  'england': 'Royaume-Uni', 'russia': 'Russie', 'georgia': 'Géorgie',
  'armenia': 'Arménie', 'south africa': 'Afrique du Sud', 'kenya': 'Kenya',
  'tanzania': 'Tanzanie', 'mexico': 'Mexique', 'brazil': 'Brésil',
  'cuba': 'Cuba', 'dominican republic': 'République Dominicaine',
  'usa': 'États-Unis', 'united states': 'États-Unis', 'canada': 'Canada'
};

function normalizeCountryToFrench(country) {
  if (!country || typeof country !== 'string') return null;
  const key = stripAccents(country);
  if (COUNTRY_EN_TO_FR[key]) return COUNTRY_EN_TO_FR[key];
  for (const frName of Object.values(COUNTRY_EN_TO_FR)) {
    if (stripAccents(frName) === key) return frName;
  }
  return country.trim().charAt(0).toUpperCase() + country.trim().slice(1).toLowerCase();
}

function dedupeCountries(arr) {
  const seen = new Set();
  const out = [];
  for (const c of (arr || [])) {
    const fr = normalizeCountryToFrench(c);
    if (!fr) continue;
    const key = stripAccents(fr);
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(fr);
  }
  return out;
}

// MAPPING ANGLAIS → FRANÇAIS POUR LES SERVICES
const SERVICE_EN_TO_FR = {
  'direct flight': 'Vol direct', 'flight': 'Vol', 'flights': 'Vols',
  'plane ticket': "Billet d'avion", 'plane tickets': "Billets d'avion",
  'round trip': 'Aller-retour', 'one way': 'Aller simple',
  'airport transfer': 'Transfert aéroport', 'airport transfers': 'Transferts aéroport',
  'transfer': 'Transfert', 'transfers': 'Transferts',
  'private transfer': 'Transfert privé', 'shared transfer': 'Transfert partagé',
  'hotel': 'Hôtel', 'hotels': 'Hôtels', 'accommodation': 'Hébergement',
  'breakfast': 'Petit déjeuner', 'breakfasts': 'Petits déjeuners',
  'half board': 'Demi-pension', 'full board': 'Pension complète',
  'all inclusive': 'Tout inclus', 'all-inclusive': 'Tout inclus',
  'guide': 'Guide', 'guided tour': 'Visite guidée', 'tour guide': 'Guide touristique',
  'excursion': 'Excursion', 'excursions': 'Excursions',
  'sightseeing': 'Visites touristiques', 'visit': 'Visite', 'visits': 'Visites',
  'lunch': 'Déjeuner', 'dinner': 'Dîner',
  'meal': 'Repas', 'meals': 'Repas',
  'drinks': 'Boissons', 'water': 'Eau',
  'visa': 'Visa', 'evisa': 'E-visa', 'e-visa': 'E-visa',
  'travel insurance': 'Assurance voyage', 'insurance': 'Assurance',
  'accompaniment': 'Accompagnement',
  'accompaniment during the stay': 'Accompagnement durant le séjour',
  'assistance': 'Assistance',
  'shopping': 'Shopping', 'beach': 'Plage', 'spa': 'Spa',
  'tips': 'Pourboires', 'gratuities': 'Pourboires',
  'optional': 'Optionnel', 'personal expenses': 'Dépenses personnelles'
};

function translateService(s) {
  if (typeof s !== 'string' || !s.trim()) return s;
  const original = s.trim();
  const key = stripAccents(original);
  if (SERVICE_EN_TO_FR[key]) return SERVICE_EN_TO_FR[key];
  return original;
}

function dedupeAndTranslateServices(arr) {
  if (!Array.isArray(arr)) return [];
  const seen = new Set();
  const out = [];
  for (const s of arr) {
    if (typeof s !== 'string' || !s.trim()) continue;
    const translated = translateService(s).trim();
    const key = stripAccents(translated);
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(translated);
  }
  return out;
}

// ----------------------------------------------------------------------------
// PAYLOAD INITIAL VIDE (même structure que Format Text Result)
// ----------------------------------------------------------------------------
const final = {
  title: null,
  agency_id: 1,
  agency_name: null,
  countries: [],
  duration_nights: null,
  airline: null,
  description: null,
  itinerary: {},
  status: 'draft',
  photo_urls: [],
  is_global_pricing: false,
  global_pricing: null,
  lead_price: null,
  services: { included: [], excluded: [] },
  steps: [],
  departures: []
};

// ----------------------------------------------------------------------------
// MERGE INTELLIGENT (priorité au premier non-null)
// ----------------------------------------------------------------------------
const mergedSources = [];

for (const item of items) {
  const p = item?.payload;
  if (!p || !item._hasData) continue;

  mergedSources.push(item.source || item.extractionType);

  // Champs simples : on garde la première valeur non-null
  final.title = final.title ?? p.title ?? null;
  final.agency_id = final.agency_id ?? p.agency_id ?? 1;
  final.agency_name = final.agency_name ?? p.agency_name ?? null;
  final.duration_nights = final.duration_nights ?? p.duration_nights ?? null;
  final.airline = final.airline ?? p.airline ?? null;
  final.description = final.description ?? p.description ?? null;

  // Itinéraire : merge profond
  if (p.itinerary && typeof p.itinerary === 'object') {
    final.itinerary = { ...final.itinerary, ...p.itinerary };
  }

  // Photos : concaténation (image et PDF peuvent en apporter)
  if (Array.isArray(p.photo_urls) && p.photo_urls.length > 0) {
    final.photo_urls = uniqueStrings([...final.photo_urls, ...p.photo_urls]);
  }

  // Pays : concaténer (la dédup FR se fera après tous les merges)
  if (Array.isArray(p.countries)) {
    final.countries = [...final.countries, ...p.countries];
  }

  // Services : concaténer (dédup + traduction se feront après tous les merges)
  if (p.services?.included) {
    final.services.included = [...final.services.included, ...p.services.included];
  }
  if (p.services?.excluded) {
    final.services.excluded = [...final.services.excluded, ...p.services.excluded];
  }

  // Steps : on prend la liste la plus longue
  if (Array.isArray(p.steps) && p.steps.length > final.steps.length) {
    final.steps = p.steps;
  }

  // Departures : on prend la liste la plus longue
  if (Array.isArray(p.departures) && p.departures.length > final.departures.length) {
    final.departures = p.departures;
  }

  // Pricing : priorité au premier qui définit is_global_pricing
  if (final.is_global_pricing === false && p.is_global_pricing === true) {
    final.is_global_pricing = true;
    final.global_pricing = p.global_pricing;
  }
  final.lead_price = final.lead_price ?? p.lead_price ?? null;
}

// ----------------------------------------------------------------------------
// NORMALISATION FINALE FRANÇAIS + DÉDUP (post-merge)
// ----------------------------------------------------------------------------
final.countries = dedupeCountries(final.countries);
final.services.included = dedupeAndTranslateServices(final.services.included);
final.services.excluded = dedupeAndTranslateServices(final.services.excluded);

// Sécurité : si lead_price toujours null mais on a un global_pricing
if (final.lead_price === null && final.global_pricing !== null) {
  final.lead_price = final.global_pricing;
}

return [{
  json: {
    ...final,
    _merged_sources: mergedSources,
    _merge_count: mergedSources.length
  }
}];

const parseResult = $input.first().json;
const detectData = $('Detect Content & Generate JobId').first().json;

const jobId = detectData.jobId || 'unknown';

function createEmptyTour() {
  return {
    title: null,
    agency_id: 1,
    agency_name: null,
    countries: [],
    duration_nights: null,
    airline: null,
    description: null,
    itinerary: {},
    status: 'draft',
    photo_urls: [],
    is_global_pricing: false,
    global_pricing: null,
    lead_price: null,
    services: {
      included: [],
      excluded: []
    },
    steps: [],
    departures: []
  };
}

function uniqueStrings(arr) {
  return [...new Set((arr || []).filter(v => typeof v === 'string' && v.trim() !== ''))];
}

function normalizeString(v) {
  return typeof v === 'string' && v.trim() !== '' ? v.trim() : null;
}

function normalizeNumber(v) {
  if (typeof v === 'number' && Number.isFinite(v)) return v;

  if (typeof v === 'string') {
    const cleaned = v
      .trim()
      .replace(/\s+/g, '')
      .replace(/,/g, '.')
      .replace(/[^\d.-]/g, '');

    if (!cleaned || cleaned === '.' || cleaned === '-' || cleaned === '-.') return null;

    const num = Number(cleaned);
    return Number.isFinite(num) ? num : null;
  }

  return null;
}

function titleCaseCity(v) {
  const s = normalizeString(v);
  if (!s) return null;

  return s
    .toLowerCase()
    .split(/\s+/)
    .map(word => word.charAt(0).toUpperCase() + word.slice(1))
    .join(' ');
}

function titleCase(v) {
  const s = normalizeString(v);
  if (!s) return null;
  return s
    .toLowerCase()
    .split(/\s+/)
    .map(w => w.charAt(0).toUpperCase() + w.slice(1))
    .join(' ');
}

function cleanAgencyName(v) {
  const s = normalizeString(v);
  if (!s) return null;
  return s
    .replace(/\n/g, ' ')
    .replace(/\s+/g, ' ')
    .replace(/^[A-Z]\s+/i, '')
    .trim();
}

function extractAgencyName(text) {
  if (!text) return null;
  const normalized = text
    .replace(/\n/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  const patterns = [
    /\b([A-Z][A-Z0-9&.' -]{1,40}\s+TRAVEL)\b/i,
    /\b([A-Z][A-Z0-9&.' -]{1,40}\s+TOURS?)\b/i,
    /\b([A-Z][A-Z0-9&.' -]{1,40}\s+VOYAGES?)\b/i,
    /\b([A-Z][A-Z0-9&.' -]{1,40}\s+AGENCY)\b/i,
    /\b(AGENCE\s+[A-Z][A-Z0-9&.' -]{1,40})\b/i
  ];
  for (const pattern of patterns) {
    const match = normalized.match(pattern);
    if (match) return cleanAgencyName(titleCase(match[1]));
  }
  return null;
}


function extractJsonString(raw) {
  if (!raw || typeof raw !== 'string') return null;

  let text = raw.trim();

  text = text.replace(/^```json\s*/i, '');
  text = text.replace(/^```\s*/i, '');
  text = text.replace(/\s*```$/i, '').trim();

  if (text.startsWith('{') && text.endsWith('}')) {
    return text;
  }

  const firstBrace = text.indexOf('{');
  const lastBrace = text.lastIndexOf('}');

  if (firstBrace !== -1 && lastBrace !== -1 && lastBrace > firstBrace) {
    return text.slice(firstBrace, lastBrace + 1);
  }

  return null;
}

function extractTextCandidates(value) {
  const results = [];

  function walk(node) {
    if (!node) return;

    if (typeof node === 'string') {
      results.push(node);
      return;
    }

    if (Array.isArray(node)) {
      for (const item of node) walk(item);
      return;
    }

    if (typeof node === 'object') {
      if (typeof node.text === 'string') results.push(node.text);
      if (typeof node.md === 'string') results.push(node.md);
      if (typeof node.markdown === 'string') results.push(node.markdown);
      if (typeof node.value === 'string') results.push(node.value);

      if (Array.isArray(node.parts)) {
        for (const part of node.parts) {
          if (typeof part?.text === 'string') results.push(part.text);
        }
      }

      if (node.content) walk(node.content);
      if (node.output) walk(node.output);
      if (node.response) walk(node.response);
      if (node.message) walk(node.message);
      if (node.pages) walk(node.pages);
      if (node.items) walk(node.items);
    }
  }

  walk(value);
  return results.filter(Boolean);
}

function normalizeHotelPricing(pricing) {
  return {
    dbl: normalizeNumber(pricing?.dbl ?? pricing?.double),
    tpl: normalizeNumber(pricing?.tpl ?? pricing?.triple),
    sgl: normalizeNumber(pricing?.sgl ?? pricing?.single),
    inf: normalizeNumber(pricing?.inf ?? pricing?.infant),
    chd_2_6: normalizeNumber(pricing?.chd_2_6 ?? pricing?.child_2_6),
    chd_5_11: normalizeNumber(pricing?.chd_5_11 ?? pricing?.child_5_11)
  };
}

function hasAnyHotelPrice(pricing) {
  if (!pricing || typeof pricing !== 'object') return false;
  return Object.values(pricing).some(v => v !== null);
}

function computeLeadPriceFromHotelPricing(pricing) {
  if (!pricing || typeof pricing !== 'object') return null;

  // Cheapest realistic adult price only.
  // Do not use child / infant prices for lead_price unless no adult price exists.
  const adultPrices = [
    normalizeNumber(pricing.tpl),
    normalizeNumber(pricing.dbl),
    normalizeNumber(pricing.sgl)
  ].filter(v => v !== null);

  if (adultPrices.length > 0) {
    return Math.min(...adultPrices);
  }

  return null;
}

function normalizeGlobalPricingAsNumber(value) {
  if (value === null || value === undefined) return null;

  if (typeof value === 'number' || typeof value === 'string') {
    return normalizeNumber(value);
  }

  // If the AI still returns old object format, extract only if there is exactly one value.
  if (typeof value === 'object' && !Array.isArray(value)) {
    const values = Object.values(value)
      .map(v => normalizeNumber(v))
      .filter(v => v !== null);

    if (values.length === 1) return values[0];
  }

  return null;
}

function extractPricesFromObject(obj) {
  const prices = [];

  function walk(node, key = '') {
    if (node === null || node === undefined) return;

    if (typeof node === 'number' && Number.isFinite(node)) {
      prices.push({
        key,
        value: node
      });
      return;
    }

    if (typeof node === 'string') {
      const n = normalizeNumber(node);
      if (n !== null && /\d/.test(node)) {
        prices.push({
          key,
          value: n
        });
      }
      return;
    }

    if (Array.isArray(node)) {
      for (const item of node) walk(item, key);
      return;
    }

    if (typeof node === 'object') {
      for (const [k, v] of Object.entries(node)) {
        walk(v, k);
      }
    }
  }

  walk(obj);
  return prices;
}

function isRoomPricingKey(key) {
  const k = String(key || '').toLowerCase();

  return [
    'dbl',
    'double',
    'tpl',
    'triple',
    'sgl',
    'single',
    'inf',
    'infant',
    'chd_2_6',
    'child_2_6',
    'chd_5_11',
    'child_5_11'
  ].includes(k);
}

function getCheapestAdultHotelPrice(steps) {
  const candidates = [];

  for (const step of steps || []) {
    for (const hotel of step.hotels || []) {
      const price = computeLeadPriceFromHotelPricing(hotel.pricing);
      if (price !== null) candidates.push(price);
    }
  }

  return candidates.length > 0 ? Math.min(...candidates) : null;
}

function dedupeDepartures(departures) {
  const seen = new Set();

  return (departures || [])
    .filter(dep =>
      dep.departure_city !== null ||
      dep.stock !== null ||
      dep.flight_departure_time !== null ||
      dep.flight_arrival_time !== null ||
      dep.return_flight_departure_time !== null ||
      dep.return_flight_arrival_time !== null
    )
    .filter(dep => {
      const key = [
        dep.departure_city,
        dep.flight_departure_time,
        dep.return_flight_departure_time
      ].join('|');

      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    });
}

// ------------------------------
// PARSE AI OUTPUT
// ------------------------------

const rawCandidates = extractTextCandidates(parseResult);

let parsed = null;
let usedRawCandidate = null;

for (const candidate of rawCandidates) {
  const jsonString = extractJsonString(candidate);
  if (!jsonString) continue;

  try {
    parsed = JSON.parse(jsonString);
    usedRawCandidate = candidate;
    break;
  } catch (error) {
    // continue
  }
}

if (!parsed) {
  return [{
    json: {
      extractionType: 'text',
      _hasData: false,
      source: 'text',
      jobId,
      debug_raw_candidates_count: rawCandidates.length,
      debug_first_candidate: rawCandidates[0] || null,
      payload: createEmptyTour()
    }
  }];
}

// ------------------------------
// BUILD PAYLOAD
// ------------------------------

const payload = createEmptyTour();

payload.title = normalizeString(parsed.title);
payload.agency_id = 1;

// Extract agency_name from AI output, with fallback to scanning the original text
const rawWhatsappText = detectData.text || '';
payload.agency_name = cleanAgencyName(parsed.agency_name) || extractAgencyName(rawWhatsappText);
payload.countries = uniqueStrings(Array.isArray(parsed.countries) ? parsed.countries : []);
payload.duration_nights = normalizeNumber(parsed.duration_nights);
payload.airline = normalizeString(parsed.airline);
payload.description = normalizeString(parsed.description);
payload.status = 'draft';

payload.photo_urls = Array.isArray(parsed.photo_urls)
  ? parsed.photo_urls.filter(v => typeof v === 'string' && v.trim() !== '')
  : [];

payload.services = {
  included: uniqueStrings(parsed?.services?.included),
  excluded: uniqueStrings(parsed?.services?.excluded)
};

// Itinerary
if (parsed.itinerary && typeof parsed.itinerary === 'object' && !Array.isArray(parsed.itinerary)) {
  const keys = Object.keys(parsed.itinerary);
  const alreadyDayFormat = keys.every(k => /^day_\d+$/i.test(k));

  if (alreadyDayFormat) {
    const normalizedItinerary = {};
    for (const [key, value] of Object.entries(parsed.itinerary)) {
      if (typeof value === 'string' && value.trim() !== '') {
        normalizedItinerary[key] = value.trim();
      }
    }
    payload.itinerary = normalizedItinerary;
  } else {
    let i = 1;
    const normalizedItinerary = {};

    for (const [, value] of Object.entries(parsed.itinerary)) {
      if (typeof value === 'string' && value.trim() !== '') {
        normalizedItinerary[`day_${i}`] = value.trim();
        i++;
      }
    }

    payload.itinerary = normalizedItinerary;
  }
}

// Steps / Hotels
if (Array.isArray(parsed.steps) && parsed.steps.length > 0) {
  payload.steps = parsed.steps
    .map((step, index) => ({
      city: titleCaseCity(step.city),
      step_order: typeof step.step_order === 'number' ? step.step_order : index + 1,
      duration_nights: normalizeNumber(step.duration_nights),
      hotels: Array.isArray(step.hotels)
        ? step.hotels.map(h => ({
            hotel_id: h.hotel_id ?? null,
            custom_hotel_name: normalizeString(h.custom_hotel_name ?? h.hotel_name ?? h.name),
            is_default: h.is_default === true,
            pricing: normalizeHotelPricing(h.pricing)
          }))
        : []
    }))
    .filter(step => step.city !== null || step.hotels.length > 0);
}

payload.steps = payload.steps
  .sort((a, b) => (a.step_order ?? 9999) - (b.step_order ?? 9999))
  .map((step, index) => ({
    ...step,
    step_order: index + 1
  }));

// Duration from steps
const stepDurationValues = payload.steps
  .map(step => normalizeNumber(step.duration_nights))
  .filter(v => v !== null);

if (payload.steps.length > 0 && stepDurationValues.length === payload.steps.length) {
  payload.duration_nights = stepDurationValues.reduce((sum, v) => sum + v, 0);
}

// Departures
if (Array.isArray(parsed.departures)) {
  payload.departures = parsed.departures
    .map(dep => {
      const explicitDepartureCity = normalizeString(dep.departure_city);
      const stock = normalizeNumber(dep.stock);
      const flightDepartureTime = normalizeString(dep.flight_departure_time);
      const flightArrivalTime = normalizeString(dep.flight_arrival_time);
      const returnFlightDepartureTime = normalizeString(dep.return_flight_departure_time);
      const returnFlightArrivalTime = normalizeString(dep.return_flight_arrival_time);

      const hasMeaningfulData =
        explicitDepartureCity !== null ||
        stock !== null ||
        flightDepartureTime !== null ||
        flightArrivalTime !== null ||
        returnFlightDepartureTime !== null ||
        returnFlightArrivalTime !== null;

      if (!hasMeaningfulData) return null;

      return {
        departure_city: explicitDepartureCity || 'Alger',
        stock,
        flight_departure_time: flightDepartureTime,
        flight_arrival_time: flightArrivalTime,
        return_flight_departure_time: returnFlightDepartureTime,
        return_flight_arrival_time: returnFlightArrivalTime
      };
    })
    .filter(Boolean);
}

payload.departures = dedupeDepartures(payload.departures);

// ------------------------------
// PRICING BUSINESS LOGIC
// ------------------------------

const parsedLeadPrice = normalizeNumber(parsed.lead_price);
const parsedGlobalPricingNumber = normalizeGlobalPricingAsNumber(parsed.global_pricing);

const hasHotelPricing = payload.steps.some(step =>
  step.hotels.some(hotel => hasAnyHotelPrice(hotel.pricing))
);

const allParsedPrices = extractPricesFromObject({
  global_pricing: parsed.global_pricing,
  steps: parsed.steps,
  lead_price: parsed.lead_price
});

// Count meaningful prices.
// If the only price is lead_price and no hotel pricing exists, it is a single global price.
const numericPriceValues = allParsedPrices.map(p => p.value);
const uniquePriceValues = [...new Set(numericPriceValues)];

const hotelRoomPriceValues = [];

for (const step of payload.steps) {
  for (const hotel of step.hotels) {
    for (const [key, value] of Object.entries(hotel.pricing || {})) {
      if (isRoomPricingKey(key) && value !== null) {
        hotelRoomPriceValues.push(value);
      }
    }
  }
}

const uniqueHotelRoomPrices = [...new Set(hotelRoomPriceValues)];

const cheapestHotelAdultPrice = getCheapestAdultHotelPrice(payload.steps);

const hasOnlyOneVisiblePrice =
  uniquePriceValues.length === 1 &&
  uniqueHotelRoomPrices.length === 0;

// Case 1:
// One single price in the whole offer.
// global_pricing is a NUMBER.
if (hasOnlyOneVisiblePrice) {
  const onlyPrice = uniquePriceValues[0];

  payload.is_global_pricing = true;
  payload.global_pricing = onlyPrice;
  payload.lead_price = onlyPrice;
}

// Case 2:
// AI explicitly returned global_pricing number and no hotel pricing exists.
else if (
  parsed.is_global_pricing === true &&
  parsedGlobalPricingNumber !== null &&
  !hasHotelPricing
) {
  payload.is_global_pricing = true;
  payload.global_pricing = parsedGlobalPricingNumber;
  payload.lead_price = parsedLeadPrice ?? parsedGlobalPricingNumber;
}

// Case 3:
// Multiple prices or hotel/room prices exist.
// global_pricing must be null.
else {
  payload.is_global_pricing = false;
  payload.global_pricing = null;

  const leadCandidates = [
    parsedLeadPrice,
    cheapestHotelAdultPrice
  ].filter(v => v !== null);

  payload.lead_price = leadCandidates.length > 0
    ? Math.min(...leadCandidates)
    : null;
}

// Final safety:
// Never copy lead_price into hotel pricing.
// Hotel pricing remains only what was explicitly parsed under hotel pricing.
for (const step of payload.steps) {
  for (const hotel of step.hotels) {
    hotel.pricing = normalizeHotelPricing(hotel.pricing);
  }
}

return [{
  json: {
    extractionType: 'text',
    _hasData: true,
    source: 'text',
    jobId,
    debug_used_candidate_preview: usedRawCandidate ? usedRawCandidate.slice(0, 300) : null,
    payload
  }
}];

const parseResult = $input.first().json;
const detectData = $('Detect Content & Generate JobId').first().json;

const jobId = detectData.jobId || 'unknown';

function createEmptyTour() {
  return {
    title: null,
    agency_id: 1,
    agency_name: null,
    countries: [],
    duration_nights: null,
    airline: null,
    description: null,
    itinerary: {},
    status: 'draft',
    photo_urls: [],
    is_global_pricing: false,
    global_pricing: null,
    lead_price: null,
    services: {
      included: [],
      excluded: []
    },
    steps: [],
    departures: []
  };
}

function uniqueStrings(arr) {
  return [...new Set((arr || []).filter(v => typeof v === 'string' && v.trim() !== ''))];
}

function normalizeString(v) {
  return typeof v === 'string' && v.trim() !== '' ? v.trim() : null;
}

function normalizeNumber(v) {
  if (typeof v === 'number' && Number.isFinite(v)) return v;

  if (typeof v === 'string') {
    const cleaned = v
      .trim()
      .replace(/\s+/g, '')
      .replace(/,/g, '.')
      .replace(/[^\d.-]/g, '');

    if (!cleaned || cleaned === '.' || cleaned === '-' || cleaned === '-.') return null;

    const num = Number(cleaned);
    return Number.isFinite(num) ? num : null;
  }

  return null;
}

function titleCaseCity(v) {
  const s = normalizeString(v);
  if (!s) return null;

  return s
    .toLowerCase()
    .split(/\s+/)
    .map(word => word.charAt(0).toUpperCase() + word.slice(1))
    .join(' ');
}

function titleCase(v) {
  const s = normalizeString(v);
  if (!s) return null;
  return s
    .toLowerCase()
    .split(/\s+/)
    .map(w => w.charAt(0).toUpperCase() + w.slice(1))
    .join(' ');
}

function cleanAgencyName(v) {
  const s = normalizeString(v);
  if (!s) return null;
  return s
    .replace(/\n/g, ' ')
    .replace(/\s+/g, ' ')
    .replace(/^[A-Z]\s+/i, '')
    .trim();
}

function extractAgencyName(text) {
  if (!text) return null;
  const normalized = text
    .replace(/\n/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  const patterns = [
    /\b([A-Z][A-Z0-9&.' -]{1,40}\s+TRAVEL)\b/i,
    /\b([A-Z][A-Z0-9&.' -]{1,40}\s+TOURS?)\b/i,
    /\b([A-Z][A-Z0-9&.' -]{1,40}\s+VOYAGES?)\b/i,
    /\b([A-Z][A-Z0-9&.' -]{1,40}\s+AGENCY)\b/i,
    /\b(AGENCE\s+[A-Z][A-Z0-9&.' -]{1,40})\b/i
  ];
  for (const pattern of patterns) {
    const match = normalized.match(pattern);
    if (match) return cleanAgencyName(titleCase(match[1]));
  }
  return null;
}


function extractJsonString(raw) {
  if (!raw || typeof raw !== 'string') return null;

  let text = raw.trim();

  text = text.replace(/^```json\s*/i, '');
  text = text.replace(/^```\s*/i, '');
  text = text.replace(/\s*```$/i, '').trim();

  if (text.startsWith('{') && text.endsWith('}')) {
    return text;
  }

  const firstBrace = text.indexOf('{');
  const lastBrace = text.lastIndexOf('}');

  if (firstBrace !== -1 && lastBrace !== -1 && lastBrace > firstBrace) {
    return text.slice(firstBrace, lastBrace + 1);
  }

  return null;
}

function extractTextCandidates(value) {
  const results = [];

  function walk(node) {
    if (!node) return;

    if (typeof node === 'string') {
      results.push(node);
      return;
    }

    if (Array.isArray(node)) {
      for (const item of node) walk(item);
      return;
    }

    if (typeof node === 'object') {
      if (typeof node.text === 'string') results.push(node.text);
      if (typeof node.md === 'string') results.push(node.md);
      if (typeof node.markdown === 'string') results.push(node.markdown);
      if (typeof node.value === 'string') results.push(node.value);

      if (Array.isArray(node.parts)) {
        for (const part of node.parts) {
          if (typeof part?.text === 'string') results.push(part.text);
        }
      }

      if (node.content) walk(node.content);
      if (node.output) walk(node.output);
      if (node.response) walk(node.response);
      if (node.message) walk(node.message);
      if (node.pages) walk(node.pages);
      if (node.items) walk(node.items);
    }
  }

  walk(value);
  return results.filter(Boolean);
}

function normalizeHotelPricing(pricing) {
  return {
    dbl: normalizeNumber(pricing?.dbl ?? pricing?.double),
    tpl: normalizeNumber(pricing?.tpl ?? pricing?.triple),
    sgl: normalizeNumber(pricing?.sgl ?? pricing?.single),
    inf: normalizeNumber(pricing?.inf ?? pricing?.infant),
    chd_2_6: normalizeNumber(pricing?.chd_2_6 ?? pricing?.child_2_6),
    chd_5_11: normalizeNumber(pricing?.chd_5_11 ?? pricing?.child_5_11)
  };
}

function hasAnyHotelPrice(pricing) {
  if (!pricing || typeof pricing !== 'object') return false;
  return Object.values(pricing).some(v => v !== null);
}

function computeLeadPriceFromHotelPricing(pricing) {
  if (!pricing || typeof pricing !== 'object') return null;

  // Cheapest realistic adult price only.
  // Do not use child / infant prices for lead_price unless no adult price exists.
  const adultPrices = [
    normalizeNumber(pricing.tpl),
    normalizeNumber(pricing.dbl),
    normalizeNumber(pricing.sgl)
  ].filter(v => v !== null);

  if (adultPrices.length > 0) {
    return Math.min(...adultPrices);
  }

  return null;
}

function normalizeGlobalPricingAsNumber(value) {
  if (value === null || value === undefined) return null;

  if (typeof value === 'number' || typeof value === 'string') {
    return normalizeNumber(value);
  }

  // If the AI still returns old object format, extract only if there is exactly one value.
  if (typeof value === 'object' && !Array.isArray(value)) {
    const values = Object.values(value)
      .map(v => normalizeNumber(v))
      .filter(v => v !== null);

    if (values.length === 1) return values[0];
  }

  return null;
}

function extractPricesFromObject(obj) {
  const prices = [];

  function walk(node, key = '') {
    if (node === null || node === undefined) return;

    if (typeof node === 'number' && Number.isFinite(node)) {
      prices.push({
        key,
        value: node
      });
      return;
    }

    if (typeof node === 'string') {
      const n = normalizeNumber(node);
      if (n !== null && /\d/.test(node)) {
        prices.push({
          key,
          value: n
        });
      }
      return;
    }

    if (Array.isArray(node)) {
      for (const item of node) walk(item, key);
      return;
    }

    if (typeof node === 'object') {
      for (const [k, v] of Object.entries(node)) {
        walk(v, k);
      }
    }
  }

  walk(obj);
  return prices;
}

function isRoomPricingKey(key) {
  const k = String(key || '').toLowerCase();

  return [
    'dbl',
    'double',
    'tpl',
    'triple',
    'sgl',
    'single',
    'inf',
    'infant',
    'chd_2_6',
    'child_2_6',
    'chd_5_11',
    'child_5_11'
  ].includes(k);
}

function getCheapestAdultHotelPrice(steps) {
  const candidates = [];

  for (const step of steps || []) {
    for (const hotel of step.hotels || []) {
      const price = computeLeadPriceFromHotelPricing(hotel.pricing);
      if (price !== null) candidates.push(price);
    }
  }

  return candidates.length > 0 ? Math.min(...candidates) : null;
}

function dedupeDepartures(departures) {
  const seen = new Set();

  return (departures || [])
    .filter(dep =>
      dep.departure_city !== null ||
      dep.stock !== null ||
      dep.flight_departure_time !== null ||
      dep.flight_arrival_time !== null ||
      dep.return_flight_departure_time !== null ||
      dep.return_flight_arrival_time !== null
    )
    .filter(dep => {
      const key = [
        dep.departure_city,
        dep.flight_departure_time,
        dep.return_flight_departure_time
      ].join('|');

      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    });
}

// ------------------------------
// PARSE AI OUTPUT
// ------------------------------

const rawCandidates = extractTextCandidates(parseResult);

// =====================================================================
// PDF MULTI-PAGES : parser TOUS les candidats JSON (1 par page)
// =====================================================================
const allParsedPages = [];
let usedRawCandidate = null;

for (const candidate of rawCandidates) {
  const jsonString = extractJsonString(candidate);
  if (!jsonString) continue;

  try {
    const pageParsed = JSON.parse(jsonString);
    if (pageParsed && typeof pageParsed === 'object') {
      allParsedPages.push(pageParsed);
      if (!usedRawCandidate) usedRawCandidate = candidate;
    }
  } catch (error) {
    // continue
  }
}

if (allParsedPages.length === 0) {
  return [{
    json: {
      extractionType: 'pdf',
      _hasData: false,
      source: 'pdf',
      jobId,
      debug_raw_candidates_count: rawCandidates.length,
      debug_first_candidate: rawCandidates[0] || null,
      payload: createEmptyTour()
    }
  }];
}

// =====================================================================
// MERGE MULTI-PAGES : consolider toutes les pages en un seul JSON
// =====================================================================

function pickLongestString(...candidates) {
  const valid = candidates.filter(s => typeof s === 'string' && s.trim().length > 0);
  if (valid.length === 0) return null;
  return valid.reduce((a, b) => (b.length > a.length ? b : a));
}

function pickFirstNonNull(...candidates) {
  for (const c of candidates) {
    if (c !== null && c !== undefined && c !== '' && !(Array.isArray(c) && c.length === 0)) {
      return c;
    }
  }
  return candidates[0] ?? null;
}

function maxNumber(...candidates) {
  const nums = candidates.map(c => normalizeNumber(c)).filter(n => n !== null);
  if (nums.length === 0) return null;
  return Math.max(...nums);
}

function unionDedupStrings(...arrays) {
  const seen = new Set();
  const out = [];
  for (const arr of arrays) {
    if (!Array.isArray(arr)) continue;
    for (const s of arr) {
      if (typeof s !== 'string' || !s.trim()) continue;
      const key = s.trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
      if (seen.has(key)) continue;
      seen.add(key);
      out.push(s.trim());
    }
  }
  return out;
}

// 1) PAYS DE RÉFÉRENCE = ceux de la 1ère page (couverture)
const firstPageCountries = Array.isArray(allParsedPages[0]?.countries)
  ? allParsedPages[0].countries.filter(c => typeof c === 'string' && c.trim())
  : [];

const referenceCountries = firstPageCountries.length > 0
  ? firstPageCountries
  : (allParsedPages.find(p => Array.isArray(p?.countries) && p.countries.length > 0)?.countries || []);

const referenceCountriesLower = new Set(
  referenceCountries.map(c => String(c).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim())
);

// 2) Filtrer les pages cohérentes (qui ont au moins un pays de référence ou aucun pays)
function pageIsCoherent(page) {
  if (!Array.isArray(page?.countries) || page.countries.length === 0) return true;
  const pageCountriesLower = page.countries.map(c =>
    String(c).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim()
  );
  return pageCountriesLower.some(c => referenceCountriesLower.has(c));
}

const coherentPages = allParsedPages.filter(pageIsCoherent);
const rejectedPages = allParsedPages.filter(p => !pageIsCoherent(p));

// 3) Construire le payload mergé
const parsed = {
  title: pickLongestString(...coherentPages.map(p => p.title).filter(Boolean)),
  agency_id: 1,
  agency_name: pickFirstNonNull(...coherentPages.map(p => p.agency_name)),
  countries: referenceCountries,
  duration_nights: maxNumber(...coherentPages.map(p => p.duration_nights)),
  airline: pickFirstNonNull(...coherentPages.map(p => p.airline).filter(Boolean)),
  description: pickLongestString(...coherentPages.map(p => p.description).filter(Boolean)),
  itinerary: {},
  status: 'draft',
  photo_urls: [],
  is_global_pricing: false,
  global_pricing: null,
  lead_price: null,
  services: { included: [], excluded: [] },
  steps: [],
  departures: []
};

// 3a) ITINERARY merge
for (const page of coherentPages) {
  if (page?.itinerary && typeof page.itinerary === 'object') {
    parsed.itinerary = { ...parsed.itinerary, ...page.itinerary };
  }
}

// 3b) SERVICES union
parsed.services.included = unionDedupStrings(
  ...coherentPages.map(p => p?.services?.included).filter(Array.isArray)
);
parsed.services.excluded = unionDedupStrings(
  ...coherentPages.map(p => p?.services?.excluded).filter(Array.isArray)
);

// 3c) STEPS consolidation par ville
const stepsByCity = new Map();

for (const page of coherentPages) {
  if (!Array.isArray(page?.steps)) continue;
  for (const step of page.steps) {
    if (!step || typeof step !== 'object') continue;
    const cityKey = String(step.city || '').toLowerCase().trim();
    if (!cityKey) continue;

    if (!stepsByCity.has(cityKey)) {
      stepsByCity.set(cityKey, {
        city: step.city,
        step_order: step.step_order || stepsByCity.size + 1,
        duration_nights: normalizeNumber(step.duration_nights),
        hotels: []
      });
    }

    const existing = stepsByCity.get(cityKey);
    const newDur = normalizeNumber(step.duration_nights);
    if (newDur !== null && (existing.duration_nights === null || newDur > existing.duration_nights)) {
      existing.duration_nights = newDur;
    }

    if (Array.isArray(step.hotels)) {
      for (const hotel of step.hotels) {
        if (!hotel || typeof hotel !== 'object') continue;
        const hotelKey = String(hotel.custom_hotel_name || hotel.hotel_id || 'default').toLowerCase().trim();
        const existingHotel = existing.hotels.find(h =>
          String(h.custom_hotel_name || h.hotel_id || 'default').toLowerCase().trim() === hotelKey
        );

        if (!existingHotel) {
          existing.hotels.push({
            hotel_id: hotel.hotel_id ?? null,
            custom_hotel_name: normalizeString(hotel.custom_hotel_name),
            is_default: hotel.is_default === true,
            pricing: normalizeHotelPricing(hotel.pricing)
          });
        } else {
          const newPricing = normalizeHotelPricing(hotel.pricing);
          for (const k of Object.keys(newPricing)) {
            if (newPricing[k] !== null && existingHotel.pricing[k] === null) {
              existingHotel.pricing[k] = newPricing[k];
            }
          }
          if (!existingHotel.custom_hotel_name && hotel.custom_hotel_name) {
            existingHotel.custom_hotel_name = normalizeString(hotel.custom_hotel_name);
          }
        }
      }
    }
  }
}

parsed.steps = Array.from(stepsByCity.values()).sort((a, b) =>
  (a.step_order || 0) - (b.step_order || 0)
);

if (parsed.steps.length === 0) {
  parsed.steps = [{
    city: null,
    step_order: 1,
    duration_nights: null,
    hotels: [{
      hotel_id: null,
      custom_hotel_name: null,
      is_default: true,
      pricing: normalizeHotelPricing({})
    }]
  }];
}

// 3d) DEPARTURES : prendre la page avec le plus de vraies dates
let bestDepartures = [];
for (const page of coherentPages) {
  if (Array.isArray(page?.departures)) {
    const validDeps = page.departures.filter(d => d && (d.date || d.departure_date || d.flight_departure_time));
    if (validDeps.length > bestDepartures.length) {
      bestDepartures = validDeps;
    }
  }
}
parsed.departures = bestDepartures;

// 3e) PRICING global
let bestGlobalPricing = null;
let bestLeadPrice = null;
let isGlobal = false;

for (const page of coherentPages) {
  if (page?.is_global_pricing === true) {
    const num = normalizeGlobalPricingAsNumber(page.global_pricing);
    if (num !== null) {
      if (bestGlobalPricing === null || num > bestGlobalPricing) {
        bestGlobalPricing = num;
        isGlobal = true;
      }
    }
  }
  const lp = normalizeNumber(page?.lead_price);
  if (lp !== null && (bestLeadPrice === null || lp < bestLeadPrice)) {
    bestLeadPrice = lp;
  }
}

parsed.is_global_pricing = isGlobal;
parsed.global_pricing = isGlobal ? bestGlobalPricing : null;
parsed.lead_price = bestLeadPrice;

// 3f) Debug info
const _debug_pdf_merge = {
  total_pages_parsed: allParsedPages.length,
  coherent_pages: coherentPages.length,
  rejected_pages: rejectedPages.length,
  reference_countries: referenceCountries,
  rejected_countries: rejectedPages.flatMap(p => p?.countries || [])
};

// ------------------------------
// BUILD PAYLOAD
// ------------------------------

const payload = createEmptyTour();

payload.title = normalizeString(parsed.title);
payload.agency_id = 1;

// Extract agency_name from AI output, with fallback to scanning the original text
// PDF: agency_name déjà mergé depuis toutes les pages, fallback regex sur texte brut
const rawPdfText = rawCandidates.join(' ');
payload.agency_name = cleanAgencyName(parsed.agency_name) || extractAgencyName(rawPdfText);
payload.countries = uniqueStrings(Array.isArray(parsed.countries) ? parsed.countries : []);
payload.duration_nights = normalizeNumber(parsed.duration_nights);
payload.airline = normalizeString(parsed.airline);
payload.description = normalizeString(parsed.description);
payload.status = 'draft';

payload.photo_urls = Array.isArray(parsed.photo_urls)
  ? parsed.photo_urls.filter(v => typeof v === 'string' && v.trim() !== '')
  : [];

payload.services = {
  included: uniqueStrings(parsed?.services?.included),
  excluded: uniqueStrings(parsed?.services?.excluded)
};

// Itinerary
if (parsed.itinerary && typeof parsed.itinerary === 'object' && !Array.isArray(parsed.itinerary)) {
  const keys = Object.keys(parsed.itinerary);
  const alreadyDayFormat = keys.every(k => /^day_\d+$/i.test(k));

  if (alreadyDayFormat) {
    const normalizedItinerary = {};
    for (const [key, value] of Object.entries(parsed.itinerary)) {
      if (typeof value === 'string' && value.trim() !== '') {
        normalizedItinerary[key] = value.trim();
      }
    }
    payload.itinerary = normalizedItinerary;
  } else {
